import {CHARACTER_CONTENT_POLICY_SPEC,parseCharacterSourceAge} from './character-content-policy-spec.mjs';
const spec=CHARACTER_CONTENT_POLICY_SPEC,fields=new RegExp(spec.sexualFields),text=new RegExp(spec.sexualText),sexualIds=new Set(spec.sexualCommandIds);
export function characterContentPolicy(start=globalThis){for(const view of [start,start?.parent,start?.top])try{const api=view?.[spec.key];if(api?.version===spec.version&&api.state==='ready')return api;}catch{}return null;}
function ordinaryDemographics(actor={}){actor??={};const rows=(elements=[])=>elements.flatMap(row=>row.type==='group'?[row,...rows(row.elements)]:[row]),fields=rows(actor.elements),ages=[actor.values?.age,actor.age,actor.information?._年龄,actor.information?.年龄,actor.信息?._年龄,actor.信息?.年龄,actor.ui?.ordinarySourceMetadata?.age],genders=[actor.values?.gender,actor.gender,actor.information?.性别,actor.信息?.性别,actor.ui?.ordinarySourceMetadata?.gender];for(const field of fields){if(['年龄','_年龄'].includes(field.label))ages.push(actor.values?.[field.id]);if(field.label==='性别')genders.push(actor.values?.[field.id]);}return{gender:genders.map(value=>String(value??'').trim()).find(Boolean)??'',age:ages.map(value=>parseCharacterSourceAge(value)).find(value=>value!==null)??null,adultConfirmed:false,status:'loading'};}
export function contentPolicyDemographics(actor){return characterContentPolicy()?.demographics(actor)??ordinaryDemographics(actor);}
export function contentPolicyEvidence(actor){return characterContentPolicy()?.evidence(actor)??{ages:[],genders:[]};}
export function contentPolicyFieldApplicable(actor,label,fieldId=null){const api=characterContentPolicy();if(api)return api.fieldApplicable(actor,label,fieldId);const paths=fieldId?Object.entries(actor?.ui?.sourceFieldPaths??{}).filter(([,id])=>id===fieldId).map(([path])=>path):[];return !fields.test([label,...paths].join(' / '));}
export function contentPolicySexualField(label){return characterContentPolicy()?.isSexualField(label)??fields.test(String(label??''));}
export function contentPolicyContextApplicable(actor,topic){return characterContentPolicy()?.contextApplicable?.(actor,topic)??false;}
export function contentPolicyCommandApplicable(actor,command,note=''){return characterContentPolicy()?.commandApplicable(actor,command,note)??(!sexualIds.has(typeof command==='string'?command:command?.id)&&!command?.adultOnly&&!command?.parts&&!text.test(String(note)));}
export function contentPolicySourceRestorationAllowed(actor,data){return characterContentPolicy()?.sourceRestorationAllowed(actor,data)??false;}
export function contentPolicyParseAge(raw){return characterContentPolicy()?.parseAge(raw)??parseCharacterSourceAge(raw);}
export function contentPolicyContainsSexualText(value){return characterContentPolicy()?.containsSexualText(value)??text.test(String(value??''));}
export function onCharacterContentPolicyReady(callback,start=globalThis){let active=true,last=null;const views=[];for(const view of [start,start?.parent,start?.top])try{if(view&&typeof view.addEventListener==='function'&&!views.includes(view))views.push(view);}catch{}const ready=()=>{const api=characterContentPolicy(start);if(active&&api&&api!==last){last=api;callback();}};for(const view of views)view.addEventListener(spec.readyEvent,ready);if(characterContentPolicy(start))queueMicrotask(ready);return()=>{active=false;for(const view of views)view.removeEventListener(spec.readyEvent,ready);};}

export function contentPolicyOperationApplicable(payload,roles={}){const api=characterContentPolicy();if(api)return api.operationApplicable(payload,roles);if(typeof payload==='string'){try{payload=JSON.parse(payload);}catch{return !text.test(payload);}}return !(payload?.功能列表??[]).some(row=>sexualIds.has(row.指令ID??row.commandId??row.id)||row.adultOnly||row.敏感部位?.length||text.test(String(row.备注??row.note??'')+' '+String(row.功能??row.指令??'')));}
